/* @prim:begin 38-wordmark */
.wordmark { font-family: var(--ds-font-mono); text-transform: uppercase; display: inline-flex; gap: 0.45em; align-items: baseline; max-width: none; }
.wordmark .wa { color: var(--cyan); font-weight: 800; letter-spacing: 0.22em; }
.wordmark .wf { color: var(--text-secondary); font-weight: 400; letter-spacing: 0.14em; }
/* @prim:end 38-wordmark */
/* @prim:begin 42-shell-nav */
.shnav { position: relative; display: flex; align-items: center; gap: 24px; min-height: 52px; padding: 0 20px; }
.shnav-brand { flex: none; font-size: var(--fs-label); }
.shnav-current { display: none; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--ds-font-sans); font-size: var(--fs-body); font-weight: 600; color: var(--cyan); }
.shnav { min-width: 0; }
.shnav-tabs { display: flex; align-items: stretch; gap: 4px; margin-left: auto; min-width: 0; overflow-x: auto; scrollbar-width: none; }
.shnav-tabs::-webkit-scrollbar { display: none; }
.shnav-tab { font: inherit; font-family: var(--ds-font-sans); font-size: var(--fs-body); font-weight: 600; color: var(--text-secondary); background: none; border: 0; border-bottom: 2px solid transparent; border-radius: 0; padding: 12px 12px 10px; min-height: 44px; display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; cursor: pointer; }
.shnav-tab:hover { color: var(--text); }
.shnav-tab[aria-selected="true"] { color: var(--cyan); border-bottom-color: var(--cyan); }
.shnav-tab:focus-visible { outline: 2px solid var(--cyan); outline-offset: -2px; border-radius: var(--ds-r-xs); }
.shnav-pill { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.02em; line-height: 1.4; padding: 2px 8px; border-radius: var(--ds-r-pill); background: var(--surface-2); border: 1px solid var(--border); color: var(--text-secondary); }
.shnav-menu { display: none; flex: none; margin-left: auto; width: 44px; height: 44px; place-items: center; padding: 0; border: 0; border-radius: var(--ds-r-sm); background: none; color: var(--text); cursor: pointer; }
.shnav-menu span, .shnav-menu span::before, .shnav-menu span::after { display: block; width: 20px; height: 2px; border-radius: var(--ds-r-xs); background: currentColor; position: relative; transition: transform var(--dur-fast) var(--ease-out); }
.shnav-menu span::before, .shnav-menu span::after { content: ""; position: absolute; left: 0; }
.shnav-menu span::before { top: -6px; }
.shnav-menu span::after { top: 6px; }
.shnav-menu[aria-expanded="true"] span { background: transparent; }
.shnav-menu[aria-expanded="true"] span::before { transform: translateY(6px) rotate(45deg); }
.shnav-menu[aria-expanded="true"] span::after { transform: translateY(-6px) rotate(-45deg); }
.shnav-menu:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
.shnav[data-mode="menu"] { justify-content: space-between; padding: 0 16px; }
.shnav[data-mode="menu"] .shnav-menu { display: inline-grid; margin-right: -8px; }
.shnav[data-mode="menu"] .shnav-brand { display: none; }
.shnav[data-mode="menu"] .shnav-current { display: block; }
.shnav[data-mode="menu"] .shnav-tabs { display: none; overflow: visible; position: absolute; top: 100%; left: 0; right: 0; z-index: 30; flex-direction: column; align-items: stretch; gap: 0; margin: 0; padding: 6px 0; background: var(--surface); border-bottom: 1px solid var(--border); box-shadow: 0 4px 12px rgba(2, 4, 8, 0.14); }
.shnav[data-mode="menu"].is-open .shnav-tabs { display: flex; animation: shnav-in var(--dur-fast) var(--ease-out); }
.shnav[data-mode="menu"] .shnav-tab { justify-content: flex-start; text-align: left; border-bottom: 0; border-radius: 0; padding: 12px 16px; color: var(--text-secondary); }
.shnav[data-mode="menu"] .shnav-tab:hover { color: var(--text); background: var(--surface-2); }
.shnav[data-mode="menu"] .shnav-tab[aria-current="true"] { color: var(--cyan); box-shadow: inset 3px 0 0 var(--cyan); }
.shnav[data-mode="menu"] .shnav-tab:focus-visible { outline-offset: -4px; border-radius: var(--ds-r-sm); }
@media (min-width: 600px) { .shnav[data-mode="menu"] .shnav-tabs { left: auto; width: 50%; border-left: 1px solid var(--border); border-bottom-left-radius: var(--ds-r-md); } }
@keyframes shnav-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .shnav-menu span, .shnav-menu span::before, .shnav-menu span::after { transition: none; } .shnav[data-mode="menu"].is-open .shnav-tabs { animation: none; } }
@media print { .shnav-menu, .shnav-tabs { display: none !important; } }
/* @prim:end 42-shell-nav */
[data-stage] .shnav, [data-state] .shnav { border: 1px solid var(--border); border-radius: var(--ds-r-sm); background: var(--surface); }
[data-state] { min-height: 300px; }

